169: impl SmartApp {
170:     fn native_resize_grips(&mut self, ctx: &egui::Context) {
171:         if IS_WEB {
172:             return;
173:         }
174:         use egui::viewport::ResizeDirection as D;
175:         let r = ctx.content_rect();
176:         let Some(p) = ctx.pointer_latest_pos() else { return };
177:         // Unified ResizeCursorOwner: 5px grips, but E/W edges are 2px so the
178:         // 14px scrollbar gutter at the right edge never fights the resize.
179:         let m = 5.0;
180:         let in_scrollbar_gutter = r.right() - p.x < 14.0 && p.x < r.right();
181:         if in_scrollbar_gutter && r.right() - p.x >= 2.0 {
182:             return; // pointer is over the scrollbar track — let it scroll
183:         }
184:         let (l, rr, t, b) = (
185:             p.x - r.left() < 2.0,
186:             r.right() - p.x < 2.0,
187:             p.y - r.top() < m,
188:             r.bottom() - p.y < m,
189:         );
190:         let dir = match (l, rr, t, b) {
191:             (true, _, true, _) => Some(D::NorthWest),
192:             (_, true, true, _) => Some(D::NorthEast),
193:             (true, _, _, true) => Some(D::SouthWest),
194:             (_, true, _, true) => Some(D::SouthEast),
195:             (true, ..) => Some(D::West),
196:             (_, true, ..) => Some(D::East),
197:             (_, _, true, _) => Some(D::North),
198:             (_, _, _, true) => Some(D::South),
199:             _ => None,
200:         };
201:         if let Some(d) = dir {
202:             ctx.set_cursor_icon(match d {
203:                 D::North | D::South => egui::CursorIcon::ResizeVertical,
204:                 D::East | D::West => egui::CursorIcon::ResizeHorizontal,
205:                 D::NorthWest | D::SouthEast => egui::CursorIcon::ResizeNwSe,
206:                 _ => egui::CursorIcon::ResizeNeSw,
207:             });
208:             if ctx.input(|i| i.pointer.primary_pressed()) {
209:                 ctx.send_viewport_cmd(egui::ViewportCommand::BeginResize(d));
210:             }
211:         }
212:     }
