214:     fn handle_keys(&mut self, ctx: &egui::Context) {
215:         use egui::Key;
216:         // the focused suite app (Terminal / Photos) owns the keyboard
217:         if IS_WEB && self.focused_app() != crate::shell::AppId::Files {
218:             let (cmd, k, comma) = ctx.input(|i| (i.modifiers.command, i.key_pressed(Key::K), i.key_pressed(Key::Comma)));
219:             if cmd && k {
220:                 self.act(Act::Palette);
221:             } else if cmd && comma {
222:                 self.app_cmd("settings");
223:             }
224:             return;
225:         }
226:         let typing = ctx.egui_wants_keyboard_input();
227:         let (cmd, shift, alt) = ctx.input(|i| (i.modifiers.command, i.modifiers.shift, i.modifiers.alt));
228:         let pressed = |k: Key| ctx.input(|i| i.key_pressed(k));
229:         let events: Vec<egui::Event> = ctx.input(|i| i.events.clone());
230:         if cmd && pressed(Key::K) {
231:             self.act(Act::Palette);
232:             return;
233:         }
234:         if cmd && pressed(Key::T) && !typing {
235:             self.act(Act::NewTab(None));
236:             return;
237:         }
238:         if cmd && pressed(Key::W) && !typing && self.tabs.len() > 1 {
239:             self.act(Act::CloseTab(self.tab_i));
240:             return;
241:         }
242:         if cmd && pressed(Key::Comma) {
243:             self.act(Act::Settings);
244:             return;
245:         }
246:         if pressed(Key::Escape) && self.search.sheet {
247:             self.act(Act::SearchSheet(false));
248:             return;
249:         }
250:         if pressed(Key::Escape) {
251:             if self.palette.open {
252:                 // palette handles its own Esc
253:             } else if self.menu.is_some() {
254:                 self.menu = None;
255:             } else if !matches!(self.modal, Modal::None) {
256:                 if let Modal::Preview(_) = self.modal {
257:                     self.be.audio.stop();
258:                 }
259:                 self.act(Act::CloseModal);
260:             } else if self.rename.is_some() {
261:                 self.rename = None;
262:             } else if self.ai.open && !typing {
263:                 self.ai.open = false;
264:             } else if self.search_active() {
265:                 self.clear_search();
266:             } else if !typing {
267:                 self.sel.clear();
268:                 self.select_mode = false;
269:             }
270:             return;
271:         }
272:         if self.palette.open {
273:             return;
274:         }
275:         // preview navigation
276:         if let Modal::Preview(l) = self.modal.clone() {
277:             let list: Vec<Location> = self.items.iter().filter(|x| x.kind.previewable()).map(|x| x.loc.clone()).collect();
278:             if let Some(i) = list.iter().position(|x| *x == l) {
279:                 if pressed(Key::ArrowRight) && i + 1 < list.len() {
280:                     self.act(Act::Preview(list[i + 1].clone()));
281:                 }
282:                 if pressed(Key::ArrowLeft) && i > 0 {
283:                     self.act(Act::Preview(list[i - 1].clone()));
284:                 }
285:             }
286:             if pressed(Key::Space) && !typing {
287:                 self.be.audio.stop();
288:                 self.act(Act::CloseModal);
289:             }
290:             return;
291:         }
292:         if !matches!(self.modal, Modal::None) {
293:             return;
294:         }
295:         if alt && pressed(Key::ArrowLeft) {
296:             self.act(Act::Back);
297:         }
298:         if alt && pressed(Key::ArrowRight) {
299:             self.act(Act::Forward);
300:         }
301:         if cmd && pressed(Key::Backslash) {
302:             self.act(Act::ToggleSidebar);
303:         }
304:         if cmd && pressed(Key::F) {
305:             self.act(Act::FocusSearch);
306:         }
307:         if pressed(Key::F5) {
308:             self.act(Act::Refresh);
309:         }
310:         if typing {
311:             return;
312:         }
313:         for e in &events {
314:             match e {
315:                 egui::Event::Copy => self.act(Act::Copy),
316:                 egui::Event::Cut => self.act(Act::Cut),
317:                 egui::Event::Paste(_) => self.act(Act::Paste),
318:                 _ => {}
319:             }
320:         }
321:         if cmd && pressed(Key::A) {
322:             self.act(Act::SelectAll);
323:         }
324:         if cmd && pressed(Key::I) {
325:             self.act(Act::Info);
326:         }
327:         if cmd && pressed(Key::D) {
328:             self.act(Act::Duplicate);
329:         }
330:         if cmd && pressed(Key::H) {
331:             self.act(Act::ToggleHidden);
332:         }
333:         if cmd && shift && pressed(Key::N) {
334:             self.act(Act::NewFolder);
335:         }
336:         if pressed(Key::F2) {
337:             if let Some(e) = self.selected().first() {
338:                 self.act(Act::Rename(e.loc.clone()));
339:             }
340:         }
341:         if pressed(Key::Delete) || (cmd && pressed(Key::Backspace)) {
342:             self.act(if shift { Act::DeleteForever } else { Act::Trash });
343:         }
344:         if pressed(Key::Enter) {
345:             self.act(Act::OpenSel);
346:         }
347:         if pressed(Key::Space) {
348:             let s = self.selected();
349:             if s.len() == 1 && s[0].kind.previewable() {
350:                 self.act(Act::Preview(s[0].loc.clone()));
351:             } else if s.len() == 1 && s[0].kind == smart_core::Kind::Audio {
352:                 self.act(Act::TogglePlayPause(s[0].loc.clone()));
353:             }
354:         }
355:         if (pressed(Key::Backspace) && !cmd) || (alt && pressed(Key::ArrowUp)) {
356:             self.act(Act::Up);
357:         }
358:         // arrow navigation
359:         if !self.search_active() && !self.items.is_empty() {
360:             let grid = self.st().grid;
361:             let cols = if grid { self.cols as i32 } else { 1 };
362:             let mut d = 0i32;
363:             if pressed(Key::ArrowRight) && grid { d = 1 }
364:             if pressed(Key::ArrowLeft) && grid { d = -1 }
365:             if pressed(Key::ArrowDown) { d = cols }
366:             if pressed(Key::ArrowUp) { d = -cols }
367:             if !alt && d != 0 {
368:                 let n = self.items.len() as i32;
369:                 let cur = self.focus.map(|f| f as i32).unwrap_or(if d > 0 { -cols.min(1) } else { n });
370:                 let next = (cur + d).clamp(0, n - 1) as usize;
371:                 self.focus = Some(next);
372:                 let loc = self.items[next].loc.clone();
373:                 if shift {
374:                     let a = self.anchor.unwrap_or(next);
375:                     let (lo, hi) = (a.min(next), a.max(next));
376:                     self.sel = self.items[lo..=hi].iter().map(|e| e.loc.clone()).collect();
377:                 } else {
378:                     self.sel = [loc].into_iter().collect();
379:                     self.anchor = Some(next);
380:                 }
381:                 self.scroll_to = Some(next);
382:             }
383:         }
384:         // single-key shortcuts (match the status-bar hints) and type-to-search
385:         if !cmd && !alt {
386:             if pressed(Key::G) { return self.act(Act::SetGrid(true)); }
387:             if pressed(Key::L) { return self.act(Act::SetGrid(false)); }
388:             if pressed(Key::D) { return self.act(Act::ToggleTheme); }
389:             if pressed(Key::T) { return self.act(Act::Modal(Modal::Tokens)); }
390:             if pressed(Key::Questionmark) { return self.act(Act::Modal(Modal::Shortcuts)); }
391:             if pressed(Key::Slash) { return self.act(Act::FocusSearch); }
392:             if self.st().typeahead {
393:                 for e in &events {
394:                     if let egui::Event::Text(t) = e {
395:                         if t.chars().all(|c| !c.is_control()) && !t.trim().is_empty() && self.rename.is_none() {
396:                             // Accumulate while typing is continuous (≤0.9 s between keys)
397:                             // so multi-character type-ahead actually works.
398:                             if self.time - self.type_at < 0.9 && !self.search.query.is_empty() {
399:                                 self.search.query.push_str(t);
400:                             } else {
401:                                 self.search.query = t.clone();
402:                             }
403:                             self.type_at = self.time;
404:                             self.search.dirty_at = self.time;
405:                             self.search.focus_next = true;
406:                             self.run_search();
407:                             return;
408:                         }
409:                     }
410:                 }
411:             }
412:         }
413:     }
414: }
