424: /// `#terminal=ls;neofetch`, `#photos`, `#photo` / `#photo=edit` / `#photo=info`, `#menu` — open the suite in a given state
425: /// (handy for sharing a view and for automated screenshots).
426: #[cfg(target_arch = "wasm32")]
427: fn deep_link(a: &mut SmartApp) {
428:     use crate::shell::AppId;
429:     let h = web_sys::window().and_then(|w| w.location().hash().ok()).unwrap_or_default();
430:     let h = h.trim_start_matches('#');
431:     let (name, arg) = h.split_once('=').unwrap_or((h, ""));
432:     match name {
433:         "terminal" => {
434:             a.open_app(AppId::Terminal);
435:             a.shell.term.command("new");
436:             for c in arg.split(';').filter(|c| !c.is_empty()) {
437:                 a.term_submit(0, c.replace("%20", " "));
438:             }
439:         }
440:         "photos" => a.open_app(AppId::Photos),
441:         "top" => {
442:             a.open_app(AppId::Terminal);
443:             a.shell.term.command("new");
444:             a.term_submit(0, "top".into());
445:         }
446:         "palette" => {
447:             match arg {
448:                 "photos" => a.open_app(AppId::Photos),
449:                 "terminal" => a.open_app(AppId::Terminal),
450:                 _ => {}
451:             }
452:             a.act(Act::Palette);
453:         }
454:         "settings" => {
455:             let app = if arg == "terminal" { AppId::Terminal } else { AppId::Photos };
456:             a.open_app(app);
457:             a.shell.settings = Some((app, 0));
458:         }
459:         "photomenu" => {
460:             a.open_app(AppId::Photos);
461:             if arg == "viewer" {
462:                 if let Some(l) = a.photos_first() {
463:                     a.photos_show(l);
464:                 }
465:                 let items = a.photos_viewer_menu();
466:                 a.open_app_menu(egui::pos2(760.0, 300.0), items);
467:             } else {
468:                 let items = a.photos_library_menu();
469:                 a.open_app_menu(egui::pos2(760.0, 300.0), items);
470:             }
471:         }
472:         "termmenu" => {
473:             a.open_app(AppId::Terminal);
474:             a.shell.term.command("new");
475:             a.term_submit(0, "ls".into());
476:             let items = a.term_menu_main();
477:             a.open_app_menu(egui::pos2(900.0, 300.0), items);
478:         }
479:         "photo" => {
480:             a.open_app(AppId::Photos);
481:             let first = a.photos_first();
482:             if let Some(l) = first {
483:                 a.photos_show(l);
484:             }
