810:     pub fn pump(&mut self, ctx: &Context) {
811:         let mut repaint = false;
812:         for ev in self.be.poll() {
813:             repaint = true;
814:             match ev {
815:                 Event::Listed { req, loc, result } => {
816:                     if req == self.listing_req {
817:                         match result {
818:                             Ok(v) => self.set_entries(v),
819:                             Err(e) => {
820:                                 self.error = Some(e);
821:                                 self.loading = false;
822:                                 self.entries.clear();
823:                                 self.rebuild_view();
824:                             }
825:                         }
826:                     } else if self.transfer.as_ref().is_some_and(|t| t.req == req) {
827:                         if let (Some(t), Ok(mut v)) = (self.transfer.as_mut(), result) {
828:                             v.retain(|e| e.is_dir && !e.hidden);
829:                             sort_entries(&mut v, SortKey::Name, true, true);
830:                             t.folders = v;
831:                             t.dest = loc;
832:                         }
833:                     }
834:                 }
835:                 Event::SearchHits { req, hits } => {
836:                     if req == self.search.req && !self.palette.open {
837:                         self.search.hits.extend(hits);
838:                         self.search.hits.sort_by(|a, b| b.score.cmp(&a.score));
839:                         self.search.hits.truncate(400);
840:                     } else if req == self.palette.req {
841:                         self.palette.hits.extend(hits);
842:                         self.palette.hits.sort_by(|a, b| b.score.cmp(&a.score));
843:                         self.palette.hits.truncate(8);
844:                     }
845:                 }
846:                 Event::SearchDone { req, scanned, elapsed_ms, cached } => {
847:                     if req == self.search.req || req == self.palette.req {
848:                         self.search.done = true;
849:                         self.search.scanned = scanned;
850:                         self.search.ms = elapsed_ms;
851:                         self.search.cached = cached;
852:                     }
853:                 }
854:                 Event::Job(j) => self.on_job(j),
855:                 Event::Thumb(t) => {
856:                     if t.size[0] == 0 {
857:                         self.thumb_failed.insert(t.loc);
858:                     } else {
859:                         let img = egui::ColorImage::from_rgba_unmultiplied(t.size, &t.rgba);
860:                         let tex = ctx.load_texture(format!("th-{}-{}", t.loc.path, t.edge), img, egui::TextureOptions::LINEAR);
861:                         let e = Tex { tex, orig: t.original };
862:                         if t.edge > 600 {
863:                             self.big_thumbs.insert(t.loc, e);
864:                             while self.big_thumbs.len() > 64 {
865:                                 if let Some(k) = self.big_thumbs.keys().next().cloned() {
866:                                     self.big_thumbs.remove(&k);
867:                                 } else {
868:                                     break;
869:                                 }
870:                             }
871:                         } else {
872:                             self.thumbs.insert(t.loc, e);
873:                             while self.thumbs.len() > 400 {
874:                                 if let Some(k) = self.thumbs.keys().next().cloned() {
875:                                     self.thumbs.remove(&k);
876:                                 } else {
877:                                     break;
878:                                 }
879:                             }
880:                         }
881:                     }
882:                 }
883:                 Event::Devices(d) => self.devices = d,
884:                 Event::Changed(l) => {
885:                     if self.current_loc().as_ref() == Some(&l) && !self.loading {
886:                         self.listing_req = self.be.list(&l);
887:                     }
888:                 }
889:                 Event::Summary { loc, items, bytes } => {
890:                     if self.places.iter().any(|p| p.loc == loc) {
891:                         self.place_counts.insert(loc.clone(), items);
892:                     }
893:                     self.summaries.insert(loc, (items, bytes));
894:                 }
895:                 Event::DeviceOp { op, result, id } => match result {
896:                     Ok(loc) => {
897:                         let name = self.devices.iter().find(|d| d.id == id).map(|d| d.name.clone()).unwrap_or(id);
898:                         match op {
899:                             "mount" => {
900:                                 self.toast(format!("Mounted {}", name), true);
901:                                 if let Some(l) = loc {
902:                                     self.navigate(Route::Loc(l));
903:                                     self.modal = Modal::None;
904:                                 }
905:                             }
906:                             "eject" => self.toast(format!("{} can now be safely removed", name), true),
907:                             _ => self.toast(format!("Unmounted {}", name), true),
908:                         }
909:                         if op != "mount" {
910:                             if let Route::Loc(l) = self.route.clone() {
911:                                 if l.fs != "file" && l.fs != "mem" {
912:                                     let h = self.be.home();
913:                                     self.navigate(Route::Loc(h));
914:                                 }
915:                             }
916:                         }
917:                         self.be.refresh_devices();
918:                     }
919:                     Err(e) => self.toast(e, false),
920:                 },
921:                 Event::Message { text, ok } => self.toast(text, ok),
922:                 Event::ArchiveDone { loc, ok, detail } => {
923:                     if ok {
924:                         self.toast(format!("{} \u{b7} {}", loc.name(), detail), true);
