293: fn dos_time(ts: i64) -> (u16, u16) {
294:     use chrono::{Datelike, Timelike};
295:     let d = { use chrono::TimeZone; chrono::Local.timestamp_opt(ts, 0).single().unwrap_or_else(chrono::Local::now) };
296:     let time = ((d.hour() as u16) << 11) | ((d.minute() as u16) << 5) | (d.second() as u16 / 2);
297:     let date = (((d.year() - 1980).max(0) as u16) << 9) | ((d.month() as u16) << 5) | d.day() as u16;
298:     (time, date)
299: }
300: impl Out<'_> {
301:     fn file(&mut self, reg: &Registry, src: &Location, name: &str) -> R<()> {
302:         let v = reg.get(&src.fs).ok_or_else(|| ZipError::Io("missing file system".into()))?;
303:         let st = v.stat(&src.path).map_err(|e| ZipError::Io(e.to_string()))?;
304:         let data = v.read(&src.path, 1 << 31).map_err(|e| ZipError::Io(e.to_string()))?;
305:         let crc = crc32(&data);
306:         let comp = if data.len() > 64 { miniz_oxide::deflate::compress_to_vec(&data, self.level) } else { data.clone() };
307:         let (method, mut payload) = if comp.len() < data.len() { (8u16, comp) } else { (0u16, data.clone()) };
308:         let (time, date) = dos_time(st.modified.unwrap_or_else(crate::model::now_secs));
309:         let mut flags = 0x0800u16; // UTF-8 names
310:         if self.password.is_some() {
311:             flags |= 1;
312:             let mut header = [0u8; 12];
313:             let mut seed = (crate::model::now_secs() as u64) ^ (crc as u64) ^ 0x9E37_79B9_7F4A_7C15;
314:             for b in header.iter_mut() {
315:                 seed ^= seed << 13;
316:                 seed ^= seed >> 7;
317:                 seed ^= seed << 17;
318:                 *b = (seed & 0xFF) as u8;
319:             }
320:             header[11] = (crc >> 24) as u8;
321:             let mut c = Crypto::new(self.password.as_deref().unwrap_or(""));
322:             c.encrypt(&mut header);
323:             c.encrypt(&mut payload);
324:             let mut p = header.to_vec();
325:             p.extend(payload);
326:             payload = p;
327:         }
328:         let nb = name.as_bytes();
329:         let mut h = Vec::with_capacity(30 + nb.len());
330:         h.extend(0x04034b50u32.to_le_bytes());
331:         h.extend(20u16.to_le_bytes());
332:         h.extend(flags.to_le_bytes());
333:         h.extend(method.to_le_bytes());
334:         h.extend(time.to_le_bytes());
335:         h.extend(date.to_le_bytes());
336:         h.extend(crc.to_le_bytes());
337:         h.extend((payload.len() as u32).to_le_bytes());
338:         h.extend((data.len() as u32).to_le_bytes());
339:         h.extend((nb.len() as u16).to_le_bytes());
340:         h.extend(0u16.to_le_bytes());
341:         h.extend(nb);
342:         self.w.write_all(&h).map_err(|e| ZipError::Io(e.to_string()))?;
343:         self.w.write_all(&payload).map_err(|e| ZipError::Io(e.to_string()))?;
344:         let mut c = Vec::with_capacity(46 + nb.len());
345:         c.extend(0x02014b50u32.to_le_bytes());
346:         c.extend(20u16.to_le_bytes());
347:         c.extend(20u16.to_le_bytes());
348:         c.extend(flags.to_le_bytes());
349:         c.extend(method.to_le_bytes());
350:         c.extend(time.to_le_bytes());
351:         c.extend(date.to_le_bytes());
352:         c.extend(crc.to_le_bytes());
353:         c.extend((payload.len() as u32).to_le_bytes());
354:         c.extend((data.len() as u32).to_le_bytes());
355:         c.extend((nb.len() as u16).to_le_bytes());
356:         c.extend(0u16.to_le_bytes());
357:         c.extend(0u16.to_le_bytes());
358:         c.extend(0u16.to_le_bytes());
359:         c.extend(0u16.to_le_bytes());
360:         c.extend(0u32.to_le_bytes());
361:         c.extend((self.offset as u32).to_le_bytes());
362:         c.extend(nb);
363:         self.cd.extend(c);
364:         self.count = self.count.saturating_add(1);
365:         self.offset += (30 + nb.len() + payload.len()) as u64;
366:         Ok(())
367:     }
368:     fn finish(mut self) -> R<()> {
369:         let cd_off = self.offset;
370:         let cd = std::mem::take(&mut self.cd);
371:         self.w.write_all(&cd).map_err(|e| ZipError::Io(e.to_string()))?;
372:         let mut e = Vec::new();
373:         e.extend(0x06054b50u32.to_le_bytes());
374:         e.extend(0u16.to_le_bytes());
375:         e.extend(0u16.to_le_bytes());
376:         e.extend(self.count.to_le_bytes());
377:         e.extend(self.count.to_le_bytes());
378:         e.extend((cd.len() as u32).to_le_bytes());
379:         e.extend((cd_off as u32).to_le_bytes());
380:         e.extend(0u16.to_le_bytes());
381:         self.w.write_all(&e).map_err(|e| ZipError::Io(e.to_string()))?;
382:         self.w.flush().map_err(|e| ZipError::Io(e.to_string()))?;
383:         Ok(())
384:     }
385: }
