527: /// Extract any common archive via system tools, emitting one progress step per line.
528: #[cfg(not(target_arch = "wasm32"))]
529: pub fn cli_extract(real: &std::path::Path, dest: &std::path::Path, total_hint: u64, mut progress: impl FnMut(&str, u64, u64)) -> Option<R<(usize, u64)>> {
530:     use std::io::{BufRead, BufReader};
531:     use std::process::Stdio;
532:     let ext = lower_ext(real);
533:     let s = real.to_string_lossy().to_string();
534:     let d = dest.to_string_lossy().to_string();
535:     let bsdtar = which(&["bsdtar"]);
536:     let (bin, args): (String, Vec<String>) = if ext == ".7z" || ext == ".rar" {
537:         ("7z".to_string(), vec!["x".into(), "-y".into(), format!("-o{d}"), s.clone()])
538:     } else if let Some(b) = bsdtar {
539:         (b, vec!["-x".into(), "-f".into(), s.clone(), "-C".into(), d.clone(), "-v".into()])
540:     } else if matches!(ext.as_str(), ".tar" | ".tar.gz" | ".tgz" | ".tar.xz" | ".txz" | ".tar.bz2" | ".tbz2") {
541:         ("tar".to_string(), vec!["-x".into(), "-f".into(), s.clone(), "-C".into(), d.clone(), "-v".into()])
542:     } else if ext == ".zip" {
543:         ("unzip".to_string(), vec!["-o".into(), "-d".into(), d.clone(), s.clone()])
544:     } else {
545:         return None;
546:     };
547:     let mut child = std::process::Command::new(&bin).args(&args).stdout(Stdio::piped()).stderr(Stdio::null()).spawn().ok()?;
548:     let stdout = child.stdout.take()?;
549:     let mut done = 0u64;
550:     let mut files = 0usize;
551:     let total = total_hint.max(1);
552:     for line in BufReader::new(stdout).lines().map_while(Result::ok) {
553:         let name = line.trim().trim_start_matches("x ").trim_start_matches("./").to_string();
554:         if !name.is_empty() {
555:             done += 1;
556:             files += 1;
557:             progress(&name, done.min(total), total);
558:         }
559:     }
560:     let ok = child.wait().map(|s| s.success()).unwrap_or(false);
561:     if ok {
562:         progress("", total, total);
563:         Some(Ok((files, done)))
564:     } else {
565:         Some(Err(ZipError::Io(format!("{bin} failed"))) )
566:     }
567: }

