311: fn passes(f: &Filters, e: &IndexEntry, fs: &str, lib: &SharedLibrary) -> bool {
312:     if let Some(d) = f.dirs {
313:         if e.dir != d {
314:             return false;
315:         }
316:     }
317:     if !f.kinds.is_empty() && !f.kinds.contains(&e.kind) {
318:         return false;
319:     }
320:     if !f.exts.is_empty() && !f.exts.iter().any(|x| e.name.to_lowercase().ends_with(&format!(".{}", x))) {
321:         return false;
322:     }
323:     if f.min_size.is_some_and(|m| e.size < m) || f.max_size.is_some_and(|m| e.size > m) {
324:         return false;
325:     }
326:     if f.modified_after.is_some_and(|m| e.modified < m) || f.modified_before.is_some_and(|m| e.modified >= m) {
327:         return false;
328:     }
329:     if !f.tags.is_empty() {
330:         let loc = Location::new(fs, e.path.clone());
331:         let l = lib.read().unwrap();
332:         let have = l.tag_ids_of(&loc);
333:         if !f.tags.iter().all(|t| have.iter().any(|h| h == t)) {
334:             return false;
335:         }
336:     }
337:     true
338: }
