411: #[cfg(not(target_arch = "wasm32"))]
412: fn score_all(entries: &[IndexEntry], terms: &[String], f: &Filters, fs: &str, lib: &SharedLibrary, root: &str) -> Vec<(u32, usize)> {
413:     use rayon::prelude::*;
414:     entries
415:         .par_chunks(16_384)
416:         .enumerate()
417:         .flat_map_iter(|(ci, chunk)| {
418:             let mut s = Scorer::new(terms);
419:             chunk
420:                 .iter()
421:                 .enumerate()
422:                 .filter_map(|(i, e)| {
423:                     if !under(&e.path, root) || !passes(f, e, fs, lib) {
424:                         return None;
425:                     }
426:                     s.score(e).map(|sc| (sc, ci * 16_384 + i))
427:                 })
428:                 .collect::<Vec<_>>()
429:         })
430:         .collect()
431: }
432: #[cfg(target_arch = "wasm32")]
433: fn score_all(entries: &[IndexEntry], terms: &[String], f: &Filters, fs: &str, lib: &SharedLibrary, root: &str) -> Vec<(u32, usize)> {
434:     let mut s = Scorer::new(terms);
435:     entries
436:         .iter()
437:         .enumerate()
438:         .filter_map(|(i, e)| if under(&e.path, root) && passes(f, e, fs, lib) { s.score(e).map(|sc| (sc, i)) } else { None })
439:         .collect()
440: }
441: 
442: fn under(path: &str, root: &str) -> bool {
443:     root == "/" || (path.starts_with(root) && (path.len() == root.len() || path.as_bytes()[root.len()] == b'/')) && path != root
444: }
445: 
446: fn content_filter(v: &dyn Vfs, cands: Vec<(u32, IndexEntry)>, needle: &str) -> Vec<(u32, IndexEntry, Option<String>)> {
447:     let mut cands: Vec<_> = cands.into_iter().filter(|(_, e)| text_like(e)).collect();
448:     cands.sort_by(|a, b| b.1.modified.cmp(&a.1.modified));
449:     cands.truncate(6000);
450:     #[cfg(not(target_arch = "wasm32"))]
451:     {
452:         use rayon::prelude::*;
453:         cands.into_par_iter().filter_map(|(s, e)| content_hit(v, &e, needle).map(|sn| (s + 50, e, Some(sn)))).collect()
454:     }
455:     #[cfg(target_arch = "wasm32")]
456:     {
457:         cands.into_iter().filter_map(|(s, e)| content_hit(v, &e, needle).map(|sn| (s + 50, e, Some(sn)))).collect()
458:     }
459: }
