461: #[allow(clippy::too_many_arguments)]
462: fn run(id: u64, q: Query, scope: Location, reg: Arc<Registry>, lib: SharedLibrary, indexes: Arc<RwLock<Vec<Arc<IndexData>>>>, cancel: Arc<AtomicBool>, tx: Sender<SearchMsg>) {
463:     let t0 = now_millis();
464:     let Some(v) = reg.get(&scope.fs) else {
465:         let _ = tx.send(SearchMsg::Done { id, scanned: 0, elapsed_ms: 0, cached: false });
466:         return;
467:     };
468:     let cached = indexes.read().unwrap().iter().find(|i| i.fs == scope.fs && under_or_eq(&scope.path, &i.root) && now_secs() - i.built_at < 600).cloned();
469:     let mk_hits = |ranked: Vec<(u32, IndexEntry, Option<String>)>, scorer: &mut Scorer, fs: &str| -> Vec<Hit> {
470:         ranked.into_iter().map(|(score, e, snippet)| Hit { matched: scorer.indices(&e.name), entry: e.to_entry(fs), score, snippet }).collect()
471:     };
472: 
473:     if let Some(ix) = cached {
474:         let ranked = score_all(&ix.entries, &q.terms, &q.filters, &ix.fs, &lib, &scope.path);
475:         let mut ranked = ranked;
476:         ranked.sort_unstable_by(|a, b| b.0.cmp(&a.0));
477:         ranked.truncate(if q.filters.content.is_some() { 20_000 } else { 400 });
478:         let mut list: Vec<(u32, IndexEntry, Option<String>)> = ranked.into_iter().map(|(s, i)| (s, ix.entries[i].clone(), None)).collect();
479:         if let Some(needle) = &q.filters.content {
480:             let c = content_filter(v.as_ref(), list.into_iter().map(|(s, e, _)| (s, e)).collect(), needle);
481:             list = c;
482:             list.sort_by(|a, b| b.0.cmp(&a.0));
483:             list.truncate(400);
484:         }
485:         let mut sc = Scorer::new(&q.terms);
486:         let hits = mk_hits(list, &mut sc, &ix.fs);
487:         let _ = tx.send(SearchMsg::Hits { id, hits });
488:         let _ = tx.send(SearchMsg::Done { id, scanned: ix.entries.len(), elapsed_ms: now_millis() - t0, cached: true });
489:         return;
490:     }
491: 
492:     // Cold path: walk, match as we go, stream batches, then keep the index.
493:     let mut scorer = Scorer::new(&q.terms);
494:     let mut all: Vec<IndexEntry> = Vec::new();
495:     let mut batch: Vec<(u32, IndexEntry, Option<String>)> = vec![];
496:     let mut last_flush = now_millis();
497:     let mut matches = 0usize;
498:     let content = q.filters.content.is_some();
499:     let scanned = walk(v.as_ref(), &scope.path, &cancel, |e| {
500:         if !content && matches < 3000 && passes(&q.filters, &e, &scope.fs, &lib) {
501:             if let Some(s) = scorer.score(&e) {
502:                 matches += 1;
503:                 batch.push((s, e.clone(), None));
504:             }
505:         }
506:         all.push(e);
507:         if batch.len() >= 64 || (now_millis() - last_flush > 80 && !batch.is_empty()) {
508:             let b = std::mem::take(&mut batch);
509:             let mut sc2 = Scorer::new(&q.terms);
510:             let hits = mk_hits(b, &mut sc2, &scope.fs);
511:             last_flush = now_millis();
512:             return tx.send(SearchMsg::Hits { id, hits }).is_ok();
513:         }
514:         true
515:     });
516:     if cancel.load(Ordering::Relaxed) {
517:         return;
518:     }
519:     if content {
520:         let cands: Vec<(u32, IndexEntry)> = all.iter().filter(|e| passes(&q.filters, e, &scope.fs, &lib)).filter_map(|e| scorer.score(e).map(|s| (s, e.clone()))).collect();
521:         let mut list = content_filter(v.as_ref(), cands, q.filters.content.as_deref().unwrap_or(""));
522:         list.sort_by(|a, b| b.0.cmp(&a.0));
523:         list.truncate(400);
524:         let hits = mk_hits(list, &mut scorer, &scope.fs);
