228: pub fn format_size(bytes: u64) -> String {
229:     const U: [&str; 5] = ["B", "KB", "MB", "GB", "TB"];
230:     if bytes < 1000 {
231:         return format!("{} B", bytes);
232:     }
233:     let mut v = bytes as f64;
234:     let mut i = 0;
235:     while v >= 1000.0 && i < 4 {
236:         v /= 1000.0;
237:         i += 1;
238:     }
239:     if v >= 100.0 || i == 1 {
240:         format!("{:.0} {}", v, U[i])
241:     } else {
242:         format!("{:.1} {}", v, U[i])
243:     }
244: }
