306: /// Natural, case-insensitive comparison ("img2" < "img10").
307: pub fn natural_cmp(a: &str, b: &str) -> std::cmp::Ordering {
308:     let (mut ai, mut bi) = (a.chars().peekable(), b.chars().peekable());
309:     loop {
310:         match (ai.peek().copied(), bi.peek().copied()) {
311:             (None, None) => return std::cmp::Ordering::Equal,
312:             (None, _) => return std::cmp::Ordering::Less,
313:             (_, None) => return std::cmp::Ordering::Greater,
314:             (Some(x), Some(y)) if x.is_ascii_digit() && y.is_ascii_digit() => {
315:                 let mut na = String::new();
316:                 let mut nb = String::new();
317:                 while let Some(c) = ai.peek().copied().filter(|c| c.is_ascii_digit()) {
318:                     na.push(c);
319:                     ai.next();
320:                 }
321:                 while let Some(c) = bi.peek().copied().filter(|c| c.is_ascii_digit()) {
322:                     nb.push(c);
323:                     bi.next();
324:                 }
325:                 let (na, nb) = (na.trim_start_matches('0'), nb.trim_start_matches('0'));
326:                 let o = na.len().cmp(&nb.len()).then_with(|| na.cmp(nb));
327:                 if o != std::cmp::Ordering::Equal {
328:                     return o;
329:                 }
330:             }
331:             (Some(x), Some(y)) => {
332:                 let o = x.to_lowercase().cmp(y.to_lowercase());
333:                 if o != std::cmp::Ordering::Equal {
334:                     return o;
335:                 }
336:                 ai.next();
337:                 bi.next();
338:             }
339:         }
340:     }
341: }
