343: pub fn sort_entries(v: &mut [Entry], key: SortKey, ascending: bool, folders_first: bool) {
344:     v.sort_by(|a, b| {
345:         if folders_first && a.is_dir != b.is_dir {
346:             return b.is_dir.cmp(&a.is_dir);
347:         }
348:         let o = match key {
349:             SortKey::Name => natural_cmp(&a.name, &b.name),
350:             SortKey::Modified => b.modified.cmp(&a.modified).then_with(|| natural_cmp(&a.name, &b.name)),
351:             SortKey::Size => b.size.cmp(&a.size).then_with(|| natural_cmp(&a.name, &b.name)),
352:             SortKey::Kind => a.kind_label().cmp(&b.kind_label()).then_with(|| natural_cmp(&a.name, &b.name)),
353:         };
354:         if ascending { o } else { o.reverse() }
355:     });
356: }

