//! Filename hardening: 255-byte / NUL / NFC / bidi / grapheme guards.
//! Centralised here so every creator (backend create/rename, ops, archive
//! extract) validates the same way. No UI dependencies.
use unicode_normalization::UnicodeNormalization;
use unicode_segmentation::UnicodeSegmentation;

/// ext4 / most filesystems: 255 bytes per component. Never truncate silently
/// (that would collide two names) — reject the name instead.
pub const MAX_NAME_BYTES: usize = 255;

/// Bidi control characters (Trojan Source style). Any of these in a filename
/// is an attack vector — reject outright. `U+200E/U+200F` (RLM/LRM) are
/// legitimate in some scripts; they are still rejected because a file manager
/// cannot safely render them in every context.
fn is_bidi_control(c: char) -> bool {
    matches!(
        c,
        '\u{202A}'..='\u{202E}' | '\u{2066}'..='\u{2069}' | '\u{200E}' | '\u{200F}' | '\u{061C}' | '\u{200B}'..='\u{200D}'
    )
}

/// Human-readable validation error for a candidate file name.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NameError(pub String);

impl std::fmt::Display for NameError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}
impl std::error::Error for NameError {}

/// Validate a single path component (not a full path).
/// Rejects: empty, ".", "..", NUL, "/", "\\", control chars, bidi controls,
/// >255 UTF-8 bytes, trailing space/dot (Windows-hostile).
pub fn validate_name(raw: &str) -> Result<(), NameError> {
    let name = raw.trim();
    if name.is_empty() {
        return Err(NameError("That name is empty".into()));
    }
    if name == "." || name == ".." {
        return Err(NameError("“.” and “..” are reserved".into()));
    }
    if name.contains('\0') {
        return Err(NameError("That name contains a NUL byte".into()));
    }
    if name.contains('/') || name.contains('\\') {
        return Err(NameError("A name cannot contain / or \\".into()));
    }
    for c in name.chars() {
        if (c < '\u{20}') || c == '\u{7f}' {
            return Err(NameError("That name contains a control character".into()));
        }
        if is_bidi_control(c) {
            return Err(NameError("That name contains bidi control characters (U+202A–U+202E, U+2066–U+2069) — blocked for safety".into()));
        }
    }
    if name.len() > MAX_NAME_BYTES {
        return Err(NameError(format!("That name is {} bytes — the limit is 255 bytes", name.len())));
    }
    if name.ends_with(' ') || name.ends_with('.') {
        return Err(NameError("A name cannot end with a space or a dot".into()));
    }
    Ok(())
}

/// True if the string contains any bidi control (used for display warnings).
pub fn has_bidi_controls(s: &str) -> bool {
    s.chars().any(is_bidi_control)
}

/// NFC-normalised form of a name. macOS (HFS+/APFS) hands out NFD; users
/// pasting names from the web often have decomposed sequences. Normalising
/// on create/rename prevents "same name, different bytes" duplicates.
pub fn normalize_nfc(name: &str) -> String {
    name.nfc().collect()
}

/// Validate *and* NFC-normalise: callers should use the returned string for
/// the actual create/rename so the on-disk name is always NFC.
pub fn checked_name(raw: &str) -> Result<String, NameError> {
    let trimmed = raw.trim();
    validate_name(trimmed)?;
    let nfc = normalize_nfc(trimmed);
    // Re-validate after normalisation (composition can change byte length).
    if nfc.len() > MAX_NAME_BYTES {
        return Err(NameError(format!("That name is {} bytes after normalisation — the limit is 255 bytes", nfc.len())));
    }
    Ok(nfc)
}

/// Grapheme-safe truncation for display: never splits a cluster (emoji,
/// combining marks, ZWJ sequences). Appends "…" when truncated.
/// `max_width_chars` is measured in grapheme clusters, not bytes/chars.
pub fn truncate_graphemes(s: &str, max_width_chars: usize) -> String {
    if max_width_chars == 0 {
        return String::new();
    }
    let clusters: Vec<&str> = s.graphemes(true).collect();
    if clusters.len() <= max_width_chars {
        return s.to_string();
    }
    let keep = max_width_chars.saturating_sub(1).max(1);
    let mut out: String = clusters[..keep].iter().cat();
    out.push('…');
    out
}

/// Estimated display width in graphemes (rough; CJK/emoji count 1 cluster
/// here — layout code pairs this with egui font metrics anyway).
pub fn grapheme_count(s: &str) -> usize {
    s.graphemes(true).count()
}

/// RTL base direction detection (first strong character). Mirrors the bidi
/// algorithm's rule for paragraph direction — used to pick alignment in
/// truncate/ellipsise so RTL names truncate on the correct side.
pub fn is_rtl(s: &str) -> bool {
    for c in s.chars() {
        let cp = c as u32;
        let rtl = matches!(cp,
            0x0590..=0x08FF | 0xFB1D..=0xFDFF | 0xFE70..=0xFEFF | 0x10D00..=0x10FFF | 0x1E800..=0x1EFFF
        );
        let ltr = matches!(cp,
            0x0041..=0x005A | 0x0061..=0x007A | 0x00C0..=0x024F
        );
        if rtl {
            return true;
        }
        if ltr {
            return false;
        }
    }
    false
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn valid_names() {
        assert!(validate_name("photo.jpg").is_ok());
        assert!(validate_name("résumé café.txt").is_ok());
    }

    #[test]
    fn rejects_nul_slash_dots() {
        assert!(validate_name("a\0b").is_err());
        assert!(validate_name("a/b").is_err());
        assert!(validate_name("a\\b").is_err());
        assert!(validate_name("").is_err());
        assert!(validate_name(".").is_err());
        assert!(validate_name("..").is_err());
        assert!(validate_name("trail ").is_err());
        assert!(validate_name("trail.").is_err());
    }

    #[test]
    fn rejects_bidi_and_controls() {
        // Trojan Source: U+202E right-to-left override
        assert!(validate_name("invoice\u{202E}gpj.txt").is_err());
        assert!(validate_name("a\u{2066}b").is_err());
        assert!(validate_name("a\u{0007}b").is_err());
        assert!(has_bidi_controls("a\u{202E}b"));
        assert!(!has_bidi_controls("plain.txt"));
    }

    #[test]
    fn enforces_255_bytes() {
        let ok = "é".repeat(127); // 2 bytes each = 254 bytes
        assert!(validate_name(&ok).is_ok());
        let over = "é".repeat(128); // 256 bytes
        assert!(validate_name(&over).is_err());
        let ascii_over = "a".repeat(256);
        assert!(validate_name(&ascii_over).is_err());
    }

    #[test]
    fn nfc_normalisation() {
        // e + combining acute U+0301 → single é U+00E9
        let nfd = "cafe\u{0301}";
        let nfc = normalize_nfc(nfd);
        assert_eq!(nfc, "café");
        assert_eq!(checked_name(nfd).unwrap(), "café");
        // checked_name rejects invalid too
        assert!(checked_name("bad\u{202E}").is_err());
    }

    #[test]
    fn grapheme_truncation() {
        let s = "a👩\u{200d}💻b"; // 3 clusters: a, 👩‍💻, b
        assert_eq!(grapheme_count(s), 3);
        assert_eq!(truncate_graphemes(s, 2), "a…");
        assert_eq!(truncate_graphemes("plain", 10), "plain");
        // combining sequence stays together
        let t = truncate_graphemes("e\u{301}e\u{301}e\u{301}", 2);
        assert_eq!(t, "e\u{301}…");
    }

    #[test]
    fn rtl_detection() {
        assert!(is_rtl("مرحبا"));
        assert!(!is_rtl("hello"));
        assert!(!is_rtl("123"));
    }
}

