/// The direct child of `root` that `loc` lives under, if any.
fn top_ancestor(root: &Location, loc: &Location) -> Option<Location> {
    let mut cur = loc.parent()?;
    while cur != *root {
        cur = cur.parent()?;
    }
    // `cur` is now the root; the step before was the top child.
    // Recover it by walking from loc up to just below root.
    let mut c = loc.parent()?;
    while c.parent().as_ref().map(|p| p != root).unwrap_or(false) {
        c = c.parent()?;
    }
    Some(c)
}

