        if done > MAX_ARCHIVE_UNCOMPRESSED {
            cleanup_partial(&dv, &created_files);
            return Err(ZipError::TooLarge("extracted data exceeds the bomb guard".into()));
        }
        files += 1;
        progress(&e.name, done, total.max(1));
    }
    Ok((files, done))
}

fn cleanup_partial(dv: &(dyn Vfs + 'static), created: &[String]) {
    for p in created {
        let _ = dv.remove(p, false);
    }
}

