pub fn watch(&mut self, loc: &Location) {
    use notify::{RecursiveMode, Watcher};
    self.watcher = None;
    let Some(path) = self.registry.get(&loc.fs).and_then(|v| v.real_path(&loc.path)) else { return };
    let (tx, l) = (self.tx.clone(), loc.clone());
    match notify::recommended_watcher(move |r: notify::Result<notify::Event>| {
        if r.is_ok() {
            let _ = tx.send(Event::Changed(l.clone()));
        }
    }) {
        Ok(mut w) => {
            match w.watch(&path, RecursiveMode::NonRecursive) {
                Ok(()) => self.watcher = Some(w),
                Err(e) => {
                    // inotify limits (max_user_watches) or stale NFS handle:
                    // say so honestly instead of silently never refreshing.
                    let _ = self.tx.send(Event::Message {
                        text: format!("Automatic refresh is limited here ({e}) — use Refresh (F5)"),
                        ok: false,
                    });
                }
            }
        }
        Err(e) => {
            let _ = self.tx.send(Event::Message {
                text: format!("File watching is unavailable ({e}) — use Refresh (F5)"),
                ok: false,
            });
        }
    }
}

