/// Modal::Conflict — Keep Both / Replace / Skip per file + All / Cancel.
fn m_conflict(&mut self, ui: &mut Ui, card: Rect) {
    let p = ui.painter().clone();
    let th = self.th.clone();
    let Some(c) = self.conflict.clone() else {
        self.acts.push(Act::CloseModal);
        return;
    };
    let verb = if c.is_move { "Move" } else { "Copy" };
    if self.modal_head(ui, card, "copy", "Files already exist", &format!("{} {} item{} → {}", verb, c.srcs.len(), if c.srcs.len() == 1 { "" } else { "s" }, c.dest.name()), true) {
        self.acts.push(Act::ConflictCancel);
    }
    let body = Rect::from_min_max(card.min + vec2(20.0, 78.0), pos2(card.right() - 20.0, card.bottom() - 66.0));
    let mut cui = ui.new_child(egui::UiBuilder::new().max_rect(body).layout(egui::Layout::top_down(egui::Align::Min)));
    cui.set_clip_rect(body.intersect(ui.clip_rect()));
    egui::ScrollArea::vertical().id_salt("conflict-list").auto_shrink([false, false]).show(&mut cui, |ui| {
        let top = ui.max_rect().top();
        let row_h = 64.0;
        ui.allocate_rect(Rect::from_min_size(pos2(body.left(), top), vec2(body.width(), c.conflicts.len() as f32 * row_h + 30.0)), Sense::hover());
        for (i, src) in c.conflicts.iter().enumerate() {
            let r = Rect::from_min_size(pos2(body.left(), top + i as f32 * row_h), vec2(body.width(), row_h - 8.0));
            grad_fill(&p, r, 12.0, th.card_top, th.card_bottom);
            rim(&p, r, 12.0, 1.2, th.rim, true, 30.0);
            let kind = self.be.stat(src).map(|e| e.kind).unwrap_or(Kind::Other);
            self.ico(&p, kind.icon(), Ic::Duo, pos2(r.left() + 28.0, r.center().y), 18.0, th.accent);
            p.text(pos2(r.left() + 48.0, r.center().y - 10.0), Align2::LEFT_CENTER, self.fit(&p, &src.name(), &f_semi(T_BODY), r.width() - 340.0), f_semi(T_BODY), th.ink1);
            let cur = c.action_for(src);
            let cur_label = match cur {
                ConflictAction::KeepBoth => "Keep both (new name)",
                ConflictAction::Replace => "Replace existing",
                ConflictAction::Skip => "Skip",
            };
            p.text(pos2(r.left() + 48.0, r.center().y + 10.0), Align2::LEFT_CENTER, cur_label, f_medium(T_META), th.ink3);
            // Per-file choice: three small buttons at the right edge.
            let labels = [("Keep", ConflictAction::KeepBoth), ("Replace", ConflictAction::Replace), ("Skip", ConflictAction::Skip)];
            let mut bx = r.right() - 12.0;
            for (label, action) in labels.iter().rev() {
                let w = self.tw(&p, label, &f_semi(11.0)) + 20.0;
                let btn = Rect::from_min_size(pos2(bx - w, r.center().y - 15.0), vec2(w, 30.0));
                bx -= w + 6.0;
                let on = cur == *action;
                let kindb = if on { Btn::Accent } else { Btn::Raised };
                if self.label_button(ui, btn, None, label, &format!("cf-{}-{}-{}", i, label, src.path), kindb).clicked() {
                    self.acts.push(Act::ConflictAct(src.clone(), *action));
                }
            }
        }
    });
    // All row + Cancel / Confirm footer.
    let all_y = card.bottom() - 108.0;
    p.text(pos2(card.left() + 20.0, all_y + 14.0), Align2::LEFT_CENTER, "Apply to all:", f_medium(T_META), th.ink3);
    let mut ax = card.left() + 110.0;
    for (label, action) in [("Keep both", ConflictAction::KeepBoth), ("Replace", ConflictAction::Replace), ("Skip", ConflictAction::Skip)] {
        let w = self.tw(&p, label, &f_semi(11.5)) + 24.0;
        let b = Rect::from_min_size(pos2(ax, all_y), vec2(w, 32.0));
        ax += w + 8.0;
        if self.label_button(ui, b, None, label, &format!("cf-all-{}", label), Btn::Raised).clicked() {
            self.acts.push(Act::ConflictAll(action));
        }
    }
    let n_src = c.srcs.len();
    let n_skip = c.conflicts.iter().filter(|s| c.action_for(s) == ConflictAction::Skip).count();
    let will_do = n_src.saturating_sub(n_skip);
    let mut cur = card.right() - 20.0;
    if self.foot_btn(ui, card, &mut cur, &format!("{} {} item{}", verb, will_do, if will_do == 1 { "" } else { "s" }), Btn::Accent, "cf-go") {
        self.acts.push(Act::ConflictConfirm);
    }
    if self.foot_btn(ui, card, &mut cur, "Cancel", Btn::Raised, "cf-cancel") {
        self.acts.push(Act::ConflictCancel);
    }
    let _ = c;
}

